class API(Library):
    """Explicit shared-library owner exposing the configured distribution families."""
    def __init__(self, path, *, dll_directories=()):
        super().__init__(path, dll_directories=dll_directories)
        self.beta = Beta(self._library)
        self.cauchy = Cauchy(self._library)
        self.chi2 = Chi2(self._library)
        self.exponential = Exponential(self._library)
        self.gamma = Gamma(self._library)
        self.laplace = Laplace(self._library)
        self.logistic = Logistic(self._library)
        self.lognormal = Lognormal(self._library)
        self.normal = Normal(self._library)
        self.t = T(self._library)
        self.weibull = Weibull(self._library)

__all__ = ["API"]
